CREATE TABLE research_gap_hold(site_id TEXT NOT NULL REFERENCES sites(site_id),gap TEXT NOT NULL,disposition TEXT NOT NULL CHECK(disposition IN ('event_hold','private_hold')),reason TEXT NOT NULL,reopen_trigger TEXT NOT NULL,reviewed_on TEXT NOT NULL,PRIMARY KEY(site_id,gap));
CREATE VIEW v_public_research_queue AS SELECT g.*, CASE WHEN g.disposition NOT LIKE 'active%' THEN g.disposition WHEN h.disposition IS NOT NULL THEN h.disposition WHEN g.next_gap='补同边界实际成本' THEN 'private_hold' WHEN g.priority='P1' THEN 'core_public' ELSE 'bounded_public' END AS public_disposition, h.reason AS gap_hold_reason,h.reopen_trigger AS gap_reopen_trigger FROM v_research_evidence_gaps g LEFT JOIN research_gap_hold h ON h.site_id=g.site_id AND h.gap=g.next_gap;
CREATE VIEW v_public_research_counts AS SELECT public_disposition,next_gap,count(*) AS site_count FROM v_public_research_queue GROUP BY 1,2;
UPDATE tasks SET next_query='2026-11受理索引已补，报批正文404；等待芜湖正式批复或报告附件，不反复查已知物料路线' WHERE site_id='CN0122';
