INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-01','CN0296','S042-01','北厂历史工艺与生产状态','表3.5-1、3.7-1','历史产品二水钨酸钠、二水钼酸钠、碳酸镍、碳酸铜；北厂生产水经隔油调节、混凝、多介质、UF回用于加水浸取；生活经化粪池接镇站。2024环评回顾2023年回转窑验收，南厂投运后拟停产拆除，不认定现已停产。工艺流程部分涉密删除；截图404，正文入库。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-02','CN0296','S042-03','公司许可边界','2025-12-25核发公示','HW50含镍废催化剂3200t/a；HW22含铜400、HW46含镍600、HW18含钨钼焚烧残渣800t/a；许可证公示不是实际处理量，厂区归属待核。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-03','CN0296','S042-04','旧许可','2024-01公示','含镍废催化剂4000t/a，与2025许可公示3200不叠加。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-04','CN0297','S042-02','迁建方案','2024-06-19拟审查','原5万吨方案调整至收购原鑫鑫化工地块的南厂区，南厂13139.2m²；南厂投运后北厂拟拆除；备案号泰姜行审备〔2023〕279，代码2104-321204-89-02-215054；非批准/验收。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-05','CN0297','S042-01','站工艺、设计水量和去向','工程组成、4.7.2、4.8.2.2表4.8.2-6','南厂10m³/h废水站；工艺水及回用水系统200t/h与冷却循环水站200m³/h另为公辅能力，不能当站处理能力。9股合计12434.4m³/a（含初雨4522），生活1140m³/a另列；污水回用，RO浓水优先混料（不足新水）。原报告称不外排为设计；厂区西南角坐标120.022992,32.643882并非中心点。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-06','CN0297','S042-01','回用与补水需求','4.7.2.1 pp135–138','焙烧前混料总用水4701m³/a（钨1778、钒钼2319、镍529、铜75），优先RO浓水，不是实际浓水量。其他工艺总用水55170.767m³/a（钨7421、钒钼7752.633、镍39364.467、铜632.667），优先回用。余热锅炉总用水51150、冷凝39840、补软水11310、软水制备用水13572m³/a；脱硫补水9000、湿电用水288、冷却补16200、设备清洗用水160、实验清洗用水180、喷淋补水43275、绿化407.26、生活1425m³/a。各类补水不记为污水产生量。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-07','CN0297','S042-01','水质源强、残余物与文本局限','表4.8.2-6、4.8.2-9/10','盐分：喷淋90000、脱硫30000、设备洗水10000mg/L设计源强；膜浓水混料去向不证明盐闭环，须核真实盐与金属平衡。污泥8t/a HW49、废UF/RO膜2t/a HW49为设计类比预测，废RO膜1t/a另列软水制备但与正文软水树脂描述有异，待核。初雨129.2m³/次、35次/a；设备洗水每年约8次；表源强与负荷保留原值。末尾部分综合及生活指标未取得清晰完整表，保留待核。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-08','CN0298','S042-05','自用催化剂与水边界','表3.3-7、4.1.1','主产品碳纳米管2000t/a非催化剂；催化剂脱水滤液返回生产最终蒸发；地洗及设备洗9m³/d、3150m³/a隔油沉淀纳管，生活5.6m³/d、1960m³/a化粪池纳管。厂区东经112°28′52.87″、北纬28°25′38.50″为报告项目位置；废油0.2t/a HW08含设备废油与隔油回收，非水量。截图405，表正文入库。','WEB_PRIMARY','公开正文/索引摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N042-09','CN0122','S042-06','受理线索','2026-11-11审批转载索引','新增受理线索，龙湾西路6号，未得正式报告正文；旧提取工艺为物料树脂，不认作废水膜。','WEB_SECONDARY','公开正文/索引摘录，未归档原件','2026-11-28');
