INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA042-01','R042-01','CN0296','north_existing','screening',1,'分质减量与回用优化','历史UF优化仅在北厂仍运行时有意义；核停产计划和膜污染、盐积累，比较维持现状与南厂替代。','conditional','实际投运、金属/盐累积、浓水合法去向、回用目标待核','INFERRED；S042-01；北厂历史，南厂投运后计划停产；非2026现行','工程候选，不视为已建设施','旧厂实际停产、流量、UF通量及排泥','分股采样、盐金属平衡、膜小试、CIP与全生命周期费用比选','现有系统维持、源头减量和物化回用',NULL,NULL,NULL,NULL,NULL,NULL,'实际六维数据不足；难度未知','2026-11-28');
