INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA042-02','R042-02','CN0297','south_design','screening',1,'分质减量与回用优化','高盐喷淋及脱硫水先分质核盐、金属相容性，评估源头减量/预处理与既有UF/RO优化；混料盐积累及固废须验证，不以高回收率直接判经济。','conditional','实际投运、金属/盐累积、浓水合法去向、回用目标待核','INFERRED；S042-01；设计10m³/h站；公辅能力不同；不证南厂投运','工程候选，不视为已建设施','膜回收率/盐金属物料平衡、浓水混料能力、投运、真实费用','分股采样、盐金属平衡、膜小试、CIP与全生命周期费用比选','现有系统维持、源头减量和物化回用',NULL,NULL,NULL,NULL,NULL,NULL,'实际六维数据不足；难度未知','2026-11-28');
